1	package credit
2	
3	import (
4		"fmt"
5		"math"
6		"sort"
7		"strconv"
8	)
9	
10	// RequirementStatus 是核对时单项要求的判定结果。
11	type RequirementStatus struct {
12		Req       *Requirement
13		Course    *Course
14		Satisfied bool
15		// Source 为 "waiver"（有效免修）或 "enrollment"（通过修读）或 ""（未满足）。
16		Source string
17		// WaiverID 是当前有效免修编号（有有效免修时以此说明学分来源）。
18		WaiverID string
19		// PassedEnrollmentID 是用于说明来源的通过修读编号：
20		// 没有有效免修时取最先提交的通过记录。
21		PassedEnrollmentID string
22		// PassedEnrollmentIDs 是该要求全部通过修读编号（修读历史），按提交先后。
23		PassedEnrollmentIDs []string
24	}
25	
26	// RejectedWaiver 是免修历史中被拒绝的申请及原因。
27	type RejectedWaiver struct {
28		Waiver *Waiver
29		Reason string
30	}
31	
32	// Report 是按学生核对学分的结果。
33	type Report struct {
34		StudentID string
35		Found     bool // 学生是否存在
36		// TotalCredits 已满足要求获得的学分之和；同一课程的多项要求各计一次，
37		// 同一要求无论通过多少次或同时有免修都只计一份。
38		// 当 Overflow 为 true 时，真实总和超出学分整数类型可表示的最大值，
39		// TotalCredits 不再是可信结果，调用方必须拒绝展示本次核对。
40		TotalCredits int
41		// Overflow 表示该学生实际获得的总学分超出学分整数类型可表示的最大值。
42		// 这只与本学生已满足的要求有关：各门课程学分本身仍然合法，未满足要求、
43		// 选课或未通过的学分都不参与累计，其他学生的记录也不影响本判定，
44		// 因此绝不能把它当作记录文件损坏。
45		Overflow     bool
46		Requirements []RequirementStatus
47		// Unmet 是未满足的要求编号（保持 Requirements 中的顺序）。
48		Unmet []string
49		// RejectedWaivers 是该学生被拒绝的免修申请及具体原因，按申请顺序。
50		RejectedWaivers []RejectedWaiver
51		// RevokedWaivers 是已撤销免修编号，按申请顺序。
52		RevokedWaivers []string
53	}
54	
55	// CheckStudent 按学生核对学分。查询没有记录的学生时 Found=false。
56	func (s *Store) CheckStudent(studentID string) Report {
57		rep := Report{StudentID: studentID}
58		if _, ok := s.studentByID[studentID]; !ok {
59			return rep
60		}
61		rep.Found = true
62	
63		// 每门课程学分为正整数，单项合法不代表总和仍落在学分整数类型范围内。
64		// 直接用 rep.TotalCredits += credit 累加会在超限时静默回绕（例如
65		// MaxInt + 1 变成负数），仍被当成成功的总学分输出。这里每次相加都
66		// 显式检查是否超出 MaxInt：一旦超出就只记录 Overflow，停止累加，
67		// 绝不用截断、回绕或“只加到某一项为止”的部分和充当结果。
68		// 是否超限只取决于该学生实际获得的学分：未满足的要求不计入，
69		// 其他学生的记录也完全不参与。
70		total := 0
71		overflow := false
72	
73		// 汇总每项要求的通过修读（按结果提交先后）。
74		type seqEntry struct {
75			id  string
76			seq int
77		}
78		passOrder := map[string][]seqEntry{}
79		for _, e := range s.enrollments {
80			if e.StudentID != studentID || e.Result != Passed {
81				continue
82			}
83			passOrder[e.ReqID] = append(passOrder[e.ReqID], seqEntry{e.ID, e.ResultSeq})
84		}
85	
