3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	func runCLI(t *testing.T, file string, args ...string) (stdout, stderr string, code int) {
12		t.Helper()
13		var out, errb bytes.Buffer
14		full := append([]string{"-f", file}, args...)
15		code = run(full, &out, &errb)
16		return out.String(), errb.String(), code
17	}
18	
19	func TestCLIEndToEnd(t *testing.T) {
20		file := filepath.Join(t.TempDir(), "records.json")
21	
22		// 文件不存在时从空记录开始。
23		out, _, code := runCLI(t, file, "student", "s1")
24		if code != 0 || !strings.Contains(out, "已登记学生") {
25			t.Fatalf("登记学生失败 code=%d out=%q", code, out)
26		}
27		if !strings.Contains(out, "从空记录开始") {
28			t.Fatalf("首次创建应提示从空记录开始，out=%q", out)
29		}
30	
31		// 课程与要求。
32		if _, _, code := runCLI(t, file, "course", "c1", "数学", "4"); code != 0 {
33			t.Fatal("登记课程失败")
34		}
35		if _, _, code := runCLI(t, file, "course", "c2", "物理", "3"); code != 0 {
36			t.Fatal("登记课程失败")
37		}
38		if out, _, code := runCLI(t, file, "req", "s1", "r1", "c1"); code != 0 {
39			t.Fatalf("登记要求失败 out=%q", out)
40		}
41		if _, _, code := runCLI(t, file, "req", "s1", "r2", "c2"); code != 0 {
42			t.Fatal("登记要求失败")
43		}
44	
45		// 同一学生重复要求被拒绝。
46		if _, errText, code := runCLI(t, file, "req", "s1", "r3", "c1"); code == 0 {
47			t.Fatalf("重复课程要求应被拒绝，err=%q", errText)
48		}
49	
50		// 修读：同学期两次，不同编号。
51		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e1"); code != 0 {
52			t.Fatal("选课 e1 失败")
53		}
54		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e2"); code != 0 {
55			t.Fatal("选课 e2 失败")
56		}
57		// e1 未通过，e2 通过。
58		if _, _, code := runCLI(t, file, "fail", "s1", "e1"); code != 0 {
59			t.Fatal("提交未通过失败")
60		}
61		if _, _, code := runCLI(t, file, "pass", "s1", "e2"); code != 0 {
62			t.Fatal("提交通过失败")
63		}
64		// 改结果应被拒绝。
65		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code == 0 {
66			t.Fatalf("未通过改通过应被拒绝，err=%q", errText)
67		}
68	
69		// r2 用免修满足。
70		if out, _, code := runCLI(t, file, "waiver", "s1", "r2", "w1", "竞赛获奖"); code != 0 ||
71			!strings.Contains(out, "有效") {
72			t.Fatalf("免修应有效 code=%d out=%q", code, out)
73		}
74	
75		// 重新打开进程核对：状态已持久化。
76		out, _, code = runCLI(t, file, "check", "s1")
77		if code != 0 {
78			t.Fatalf("核对失败 code=%d out=%q", code, out)
79		}
80		if !strings.Contains(out, "总学分：7") {
81			t.Fatalf("总学分应为 7（4+3），out=%q", out)
82		}
83		if !strings.Contains(out, "通过修读 e2") {
84			t.Fatalf("应以通过修读 e2 说明 r1 来源，out=%q", out)
85		}
86		if !strings.Contains(out, "有效免修 w1") {
87			t.Fatalf("应以免修 w1 说明 r2 来源，out=%q", out)
88		}
89		if strings.Contains(out, "未满足要求：[") {
90			t.Fatalf("不应有未满足要求，out=%q", out)
91		}
92	
93		// 停开课程后不能新增修读。
94		if _, _, code := runCLI(t, file, "course-close", "c2"); code != 0 {
95			t.Fatal("停开课程失败")
96		}
