24	// seqLimitBase 构造结构完整、引用齐全的基础记录：s1 的要求 r1 指向
25	// 4 学分课程 c1。计数器与修读由各用例自行补充。
26	func seqLimitBase() *diskRecord {
27		return &diskRecord{
28			Version:      1,
29			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
30			Students:     []diskStudent{{ID: "s1"}},
31			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
32		}
33	}
