37	// assertSeqExhaustedCLI 断言一次首次成绩提交在编号用尽时被拒绝：退出码 1、
38	// stdout 无任何提交提示，stderr 点名学生、修读并说明编号已用尽。
39	func assertSeqExhaustedCLI(t *testing.T, file string, args []string, student, enr, label string) {
40		t.Helper()
41		out, errText, code := runCLI(t, file, args...)
42		if code != exitRejected {
