44				label, code, out, errText)
45		}
46		if out != "" || strings.Contains(out, "结果已提交") ||
47			strings.Contains(out, "已提交过相同结果") {
48			t.Fatalf("%s：被拒绝时标准输出不能出现提交成功或返回已提交成绩的提示，out=%q",
49				label, out)
50		}
51		for _, want := range []string{
52			student, enr, "成绩提交顺序编号已用尽", "无法提交新的成绩", maxIntText,
53		} {
54			if !strings.Contains(errText, want) {
55				t.Fatalf("%s：标准错误应包含 %q，err=%q", label, want, errText)
56			}
57		}
58		if strings.Contains(errText, "损坏") {
59			t.Fatalf("%s：编号用尽不是记录文件损坏，err=%q", label, errText)
60		}
61	}
