63	// TestCLISubmitResultSeqExhaustedRejectsPassAndFail 计数器到顶后，对仍处于
64	// 选课的修读 pass/fail 都必须退出码 1：不输出成功提示、修读保持选课、
65	// 没有学分，记录文件逐字节不变，核对结论不变。
66	func TestCLISubmitResultSeqExhaustedRejectsPassAndFail(t *testing.T) {
67		d := seqLimitBase()
68		d.Enrollments = []diskEnr{
69			// 一份早先的通过占掉 MaxInt-1，另有仍处于选课的 e2。
70			enrRecord("e1", "s1", "r1", "2024春", "passed", 9223372036854775806),
71			{ID: "e2", Student: "s1", Req: "r1", Term: "2024秋", Result: "enrolled"},
72		}
73		d.NextResultSeq = 9223372036854775807
74		file, raw := writeDiskRecord(t, d)
75	
76		for _, cmd := range []string{"pass", "fail"} {
77			assertSeqExhaustedCLI(t, file, []string{cmd, "s1", "e2"}, "s1", "e2", cmd+" 选课修读")
78			show, _, code := runCLI(t, file, "show", "s1")
79			if code != 0 || !strings.Contains(show, "修读 e2：要求 r1，学期 2024秋，结果：选课") {
80				t.Fatalf("%s 被拒后 e2 应保持选课，code=%d show=%q", cmd, code, show)
