92	// TestCLISubmitResultSeqLastSlotSubmission 计数距上限差一时，最后一次首次
93	// 提交正常完成并落盘（pass 与 fail 两种入口都覆盖），提交先后关系保留；
94	// 到顶之后新的首次提交被拒绝。
95	func TestCLISubmitResultSeqLastSlotSubmission(t *testing.T) {
96		t.Run("最后一次提交通过", func(t *testing.T) {
97			d := seqLimitBase()
98			d.Enrollments = []diskEnr{
