100				{ID: "e2", Student: "s1", Req: "r1", Term: "2024秋", Result: "enrolled"},
101				{ID: "e3", Student: "s1", Req: "r1", Term: "2025春", Result: "enrolled"},
102			}
103			d.NextResultSeq = 9223372036854775806
104			file, _ := writeDiskRecord(t, d)
105	
106			// 距上限恰好还差一：最后一次合法的首次提交。
107			out, _, code := runCLI(t, file, "pass", "s1", "e2")
108			if code != 0 || !strings.Contains(out, "修读 e2 结果已提交：通过") {
109				t.Fatalf("差一号时应允许最后一次通过提交，code=%d out=%q", code, out)
110			}
111			// 落盘后再打开：e2 取得 MaxInt 序号；check/show 正常，来源是 e2
