124			assertSeqExhaustedCLI(t, file, []string{"pass", "s1", "e3"}, "s1", "e3", "到顶后 pass")
125			show, _, _ = runCLI(t, file, "show", "s1")
126			if !strings.Contains(show, "修读 e3：要求 r1，学期 2025春，结果：选课") ||
127				!strings.Contains(show, "结果：通过") {
128				t.Fatalf("e3 应保持选课、e2 保持通过，show=%q", show)
129			}
130		})
131	
132		t.Run("最后一次提交未通过", func(t *testing.T) {
133			d := seqLimitBase()
134			d.Enrollments = []diskEnr{
135				{ID: "e1", Student: "s1", Req: "r1", Term: "2024春", Result: "enrolled"},
136				{ID: "e2", Student: "s1", Req: "r1", Term: "2024秋", Result: "enrolled"},
137			}
