167	// TestCLISubmitResultSeqExhaustedIdempotentAndConflict 到顶后：重复提交相同
168	// 结果幂等成功并返回原记录、不改文件；改成另一结果按原有冲突规则拒绝，
169	// 错误不能说成编号用尽。
170	func TestCLISubmitResultSeqExhaustedIdempotentAndConflict(t *testing.T) {
171		d := seqLimitBase()
172		d.Courses = append(d.Courses, diskCourse{ID: "c2", Name: "大学物理", Credit: 3, Open: true})
173		d.Requirements = append(d.Requirements, diskReq{ID: "r2", Student: "s1", Course: "c2"})
174		d.Enrollments = []diskEnr{
175			enrRecord("e1", "s1", "r1", "2024春", "passed", 9223372036854775806),
176			enrRecord("e2", "s1", "r2", "2024春", "failed", 9223372036854775807),
177		}
178		d.NextResultSeq = 9223372036854775807
179		file, raw := writeDiskRecord(t, d)
180	
181		// 重复提交相同结果：幂等成功（退出码 0），返回原记录、不增学分。
182		out, _, code := runCLI(t, file, "pass", "s1", "e1")
183		if code != 0 || !strings.Contains(out, "已提交过相同结果") ||
184			!strings.Contains(out, "通过") {
185			t.Fatalf("到顶后重复通过应幂等返回原记录，code=%d out=%q", code, out)
186		}
187		out, _, code = runCLI(t, file, "fail", "s1", "e2")
188		if code != 0 || !strings.Contains(out, "已提交过相同结果") ||
189			!strings.Contains(out, "未通过") {
190			t.Fatalf("到顶后重复未通过应幂等返回原记录，code=%d out=%q", code, out)
191		}
192		assertFileByteIdentical(t, file, raw, "幂等重复之后：")
193		// 学分仍是 r1 的一份 4（r2 未通过不计）。
194		check, _, _ := runCLI(t, file, "check", "s1")
195		if !strings.Contains(check, "总学分：4") {
196			t.Fatalf("幂等重复不应改变学分，check=%q", check)
197		}
198	
199		// 改成另一结果：原有冲突规则，退出码 1，不能报编号用尽。
200		out, errText, code := runCLI(t, file, "fail", "s1", "e1")
201		if code != exitRejected || out != "" || !strings.Contains(errText, "不能改为") {
202			t.Fatalf("通过改未通过应按冲突拒绝，code=%d out=%q err=%q", code, out, errText)
203		}
204		if strings.Contains(errText, "编号已用尽") {
205			t.Fatalf("改结果冲突不能报成编号用尽，err=%q", errText)
206		}
207		out, errText, code = runCLI(t, file, "pass", "s1", "e2")
208		if code != exitRejected || out != "" || !strings.Contains(errText, "不能改为") {
209			t.Fatalf("未通过改通过应按冲突拒绝，code=%d out=%q err=%q", code, out, errText)
210		}
211		assertFileByteIdentical(t, file, raw, "冲突拒绝之后：")
212		show, _, _ := runCLI(t, file, "show", "s1")
213		if !strings.Contains(show, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
214			!strings.Contains(show, "修读 e2：要求 r2，学期 2024春，结果：未通过") {
215			t.Fatalf("原结果都应保留，show=%q", show)
216		}
217	}
