219	// TestCLISubmitResultSeqExhaustedNotBypassedByPassOrWaiver 要求已由另一份
220	// 通过修读或有效免修满足时，编号到顶后新的首次成绩提交仍被拒绝。
221	func TestCLISubmitResultSeqExhaustedNotBypassedByPassOrWaiver(t *testing.T) {
222		t.Run("同一要求已有另一份通过", func(t *testing.T) {
223			d := seqLimitBase()
224			d.Enrollments = []diskEnr{
225				enrRecord("e1", "s1", "r1", "2024春", "passed", 9223372036854775807),
