236			}
237			assertFileByteIdentical(t, file, raw, "已有通过拒绝之后：")
238		})
239	
240		t.Run("要求已由有效免修满足", func(t *testing.T) {
241			d := seqLimitBase()
242			d.Waivers = []diskWaiver{{
243				ID: "w1", Student: "s1", Req: "r1", Basis: "学科竞赛获奖", Status: "approved",
244			}}
245			d.Enrollments = []diskEnr{
246				{ID: "e1", Student: "s1", Req: "r1", Term: "2024春", Result: "enrolled"},
247			}
248			d.NextResultSeq = 9223372036854775807
249			file, raw := writeDiskRecord(t, d)
250	
251			// 免修已满足要求，但新成绩仍不能提交。
252			assertSeqExhaustedCLI(t, file, []string{"pass", "s1", "e1"}, "s1", "e1", "有效免修时 pass")
253			assertSeqExhaustedCLI(t, file, []string{"fail", "s1", "e1"}, "s1", "e1", "有效免修时 fail")
254			check, _, code := runCLI(t, file, "check", "s1")
255			if code != 0 || !strings.Contains(check, "总学分：4") ||
256				!strings.Contains(check, "来源为有效免修 w1") {
257				t.Fatalf("有效免修的满足状态与来源应不变，code=%d check=%q", code, check)
258			}
259			show, _, _ := runCLI(t, file, "show", "s1")
260			if !strings.Contains(show, "修读 e1：要求 r1，学期 2024春，结果：选课") {
261				t.Fatalf("e1 应保持选课，show=%q", show)
262			}
263			assertFileByteIdentical(t, file, raw, "免修情形拒绝之后：")
264		})
265	}
