267	// TestCLISubmitResultSeqExhaustedUnknownStudentAndEnrollment 编号到顶后，
268	// 学生或本人名下修读不存在仍给原有的不存在提示（退出码 1），不能借用
269	// 他人修读，也不改文件。
270	func TestCLISubmitResultSeqExhaustedUnknownStudentAndEnrollment(t *testing.T) {
271		d := seqLimitBase()
272		d.Students = append(d.Students, diskStudent{ID: "s2"})
273		d.Enrollments = []diskEnr{
274			enrRecord("e1", "s1", "r1", "2024春", "passed", 9223372036854775807),
275		}
276		d.NextResultSeq = 9223372036854775807
277		file, raw := writeDiskRecord(t, d)
