294	}
295	
296	// TestCLISubmitResultSeqExhaustedFileStaysReadable 编号到顶的合法记录不是
297	// 内容损坏：check/show/list-courses 都正常，只读访问逐字节不改文件；
298	// 编号到顶后整个文件无法再写入新的首次成绩，但已有学分与来源照常可查。
299	func TestCLISubmitResultSeqExhaustedFileStaysReadable(t *testing.T) {
300		d := seqLimitBase()
301		d.Enrollments = []diskEnr{
302			enrRecord("e1", "s1", "r1", "2024春", "passed", 9223372036854775807),
303			{ID: "e2", Student: "s1", Req: "r1", Term: "2024秋", Result: "enrolled"},
304		}
305		d.NextResultSeq = 9223372036854775807
306		file, raw := writeDiskRecord(t, d)
307	
308		// 只读命令全部正常，且不改文件。
309		out, _, code := runCLI(t, file, "check", "s1")
310		if code != 0 || !strings.Contains(out, "总学分：4") ||
311			!strings.Contains(out, "来源为通过修读 e1") ||
312			!strings.Contains(out, "未满足要求：（无）") {
313			t.Fatalf("到顶记录应正常核对，code=%d out=%q", code, out)
314		}
315		out, _, code = runCLI(t, file, "show", "s1")
316		if code != 0 || !strings.Contains(out, "结果：通过") || !strings.Contains(out, "结果：选课") {
317			t.Fatalf("到顶记录应可正常查看，code=%d out=%q", code, out)
318		}
319		out, _, code = runCLI(t, file, "list-courses")
320		if code != 0 || !strings.Contains(out, "课程 c1《高等数学》4 学分") {
321			t.Fatalf("到顶记录应可正常列出课程，code=%d out=%q", code, out)
322		}
323		assertFileByteIdentical(t, file, raw, "只读访问之后：")
324	
325		// 不存在学生仍走原有不存在提示，而不是文件损坏。
326		_, errText, code := runCLI(t, file, "check", "ghost")
327		if code != exitRejected || !strings.Contains(errText, "不存在") {
328			t.Fatalf("不存在学生行为应不变，code=%d err=%q", code, errText)
329		}
