66	// TestCLIDuplicateResultSeqRejectsAllCommands 文件完整可解析、引用齐全，
67	// 但同一学生同一学期的两条不同修读（两次通过）共用同一个正整数提交序号：
68	// 所有只读与写入类命令都必须退出码 2，不输出业务结果，错误点名文件与序号，
69	// 原文件逐字节保留。
70	func TestCLIDuplicateResultSeqRejectsAllCommands(t *testing.T) {
71		d := seqDupBase()
72		d.Enrollments = []diskEnr{
73			enrRecord("e1", "s1", "r1", "2024春", "passed", 3),
74			enrRecord("e2", "s1", "r1", "2024春", "passed", 3),
75		}
76		d.NextResultSeq = 3
77		file, raw := writeDiskRecord(t, d)
78	
79		// 只读核对：不能挑其中一条通过记录继续核对，也不能出现总学分。
80		assertSeqDupAccessRejected(t, file, []string{"check", "s1"}, "3", "check 当事学生")
81		// 历史查看同样拒绝。
82		assertSeqDupAccessRejected(t, file, []string{"show", "s1"}, "3", "show 当事学生")
83		// 与冲突修读无关的只读命令也要在加载阶段整份拒绝。
84		assertSeqDupAccessRejected(t, file, []string{"list-courses"}, "3", "list-courses")
85		// 写入类命令：不能报告登记成功，更不能把冲突文件覆盖成“干净”的新记录。
86		assertSeqDupAccessRejected(t, file, []string{"student", "s9"}, "3", "写入类命令 student")
87		// 针对文件里根本不存在的学生核对：文件整体不可读，仍退出码 2。
88		assertSeqDupAccessRejected(t, file, []string{"check", "ghost"}, "3", "check 其他学生")
89	
90		assertFileByteIdentical(t, file, raw, "全部访问后：")
91	}
