346	// TestCLISameEnrollmentIDAcrossStudentsDifferentSeq 不同学生共用修读编号与
347	// 学期、但提交序号不同：各自的记录正常读取、核对各归本人，不能因编号或
348	// 学期相同误报冲突或串记录；文件排列与提交先后不一致时结论不变。
349	func TestCLISameEnrollmentIDAcrossStudentsDifferentSeq(t *testing.T) {
350		d := &diskRecord{
351			Version: 1,
352			Courses: []diskCourse{
353				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
354				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
355			},
356			Students: []diskStudent{{ID: "s1"}, {ID: "s2"}},
357			Requirements: []diskReq{
358				{ID: "r1", Student: "s1", Course: "c1"},
359				{ID: "r1", Student: "s2", Course: "c2"},
360			},
361			Enrollments: []diskEnr{
362				// 后提交的 s2 记录排在文件前面：来源只看本人的提交序号。
363				enrRecord("e1", "s2", "r1", "2024春", "passed", 2),
364				enrRecord("e1", "s1", "r1", "2024春", "passed", 1),
365			},
366			NextResultSeq: 2,
367		}
368		file, raw := writeDiskRecord(t, d)
369	
370		out, _, code := runCLI(t, file, "check", "s1")
371		if code != 0 {
372			t.Fatalf("s1 的合法记录应正常核对，code=%d out=%q", code, out)
373		}
374		if !strings.Contains(out, "总学分：4") ||
375			!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：已满足") ||
376			!strings.Contains(out, "来源为通过修读 e1") {
377			t.Fatalf("s1 应凭本人 e1 获得本人 4 学分课程，out=%q", out)
378		}
379	
380		out, _, code = runCLI(t, file, "check", "s2")
381		if code != 0 {
382			t.Fatalf("s2 的合法记录应正常核对，code=%d out=%q", code, out)
383		}
384		if !strings.Contains(out, "总学分：3") ||
385			!strings.Contains(out, "要求 r1（课程 c2《线性代数》，3 学分）：已满足") ||
386			!strings.Contains(out, "来源为通过修读 e1") {
387			t.Fatalf("s2 应凭本人 e1 获得本人 3 学分课程，编号相同不构成冲突，out=%q", out)
388		}
389	
390		// show 各归各：只能看到本人的修读与课程，不能串到另一人。
391		show1, _, _ := runCLI(t, file, "show", "s1")
392		if !strings.Contains(show1, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
393			strings.Contains(show1, "线性代数") {
394			t.Fatalf("s1 的历史应只含本人修读与本人课程，out=%q", show1)
395		}
396		show2, _, _ := runCLI(t, file, "show", "s2")
397		if !strings.Contains(show2, "修读 e1：要求 r1，学期 2024春，结果：通过") ||
398			strings.Contains(show2, "高等数学") {
399			t.Fatalf("s2 的历史应只含本人修读与本人课程，out=%q", show2)
400		}
401	
402		assertFileByteIdentical(t, file, raw, "跨学生同号不同序号只读之后：")
403	}
