1	package main
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件从命令行入口回归“读取已有记录时，同一学生的同一要求只能有一份
12	// 有效免修”。这类冲突无法经正常申请流程落入文件（第二份申请提交时就会被
13	// 拒绝），所以用例直接写出结构完整、可解析的记录文件，每条断言都重新打开
14	// 进程访问它：
15	//   - 两份编号不同、状态均为有效的免修并存：无论 check、show 还是写入类
16	//     命令，都沿用文件内容损坏的退出码 2，不输出任何业务结果，错误点名
17	//     问题文件、所属学生、目标要求与两个免修编号，原文件逐字节保留；
18	//   - 通过修读、无关学生的合法记录都不能掩盖或分担这份冲突；
19	//   - 一份有效免修与已拒绝、已撤销申请共存是合法记录：核对只认有效来源、
20	//     学分只计一次，历史与原因完整可查，只读访问不改文件；
21	//   - 唯一性按学生隔离：不同学生共用要求编号与免修编号时各自正常核对。
22	
23	// 以下结构仅用于在测试里拼出与磁盘格式一致的 JSON（字段标签与
24	// credit.fileData 保持一致）。
25	type diskRecord struct {
26		Version       int           `json:"version"`
27		Courses       []diskCourse  `json:"courses"`
28		Students      []diskStudent `json:"students"`
29		Requirements  []diskReq     `json:"requirements"`
30		Enrollments   []diskEnr     `json:"enrollments"`
31		Waivers       []diskWaiver  `json:"waivers"`
32		NextResultSeq int           `json:"nextResultSeq"`
33	}
34	
35	type diskCourse struct {
36		ID     string `json:"id"`
37		Name   string `json:"name"`
38		Credit int    `json:"credit"`
39		Open   bool   `json:"open"`
40	}
41	type diskStudent struct {
42		ID string `json:"id"`
43	}
44	type diskReq struct {
45		ID      string `json:"id"`
46		Student string `json:"student"`
47		Course  string `json:"course"`
48	}
49	type diskEnr struct {
50		ID        string `json:"id"`
51		Student   string `json:"student"`
52		Req       string `json:"req"`
53		Term      string `json:"term"`
54		Result    string `json:"result"`
55		ResultSeq int    `json:"resultSeq,omitempty"`
56	}
57	type diskWaiver struct {
58		ID      string `json:"id"`
59		Student string `json:"student"`
60		Req     string `json:"req"`
61		Basis   string `json:"basis"`
62		Status  string `json:"status"`
63		Reason  string `json:"reason,omitempty"`
64	}
65	
66	// writeDiskRecord 把记录序列化到临时文件，返回路径与原始字节。
67	func writeDiskRecord(t *testing.T, d *diskRecord) (string, []byte) {
68		t.Helper()
69		raw, err := json.MarshalIndent(d, "", "  ")
70		if err != nil {
71			t.Fatalf("序列化记录失败：%v", err)
72		}
73		raw = append(raw, '\n')
74		file := filepath.Join(t.TempDir(), "records.json")
75		if err := os.WriteFile(file, raw, 0o600); err != nil {
76			t.Fatalf("写入记录文件失败：%v", err)
77		}
78		return file, raw
79	}
80	
81	// assertFileByteIdentical 断言记录文件与写入时的内容逐字节一致。
82	func assertFileByteIdentical(t *testing.T, file string, want []byte, label string) {
83		t.Helper()
84		got, err := os.ReadFile(file)
85		if err != nil {
86			t.Fatalf("读取记录文件失败：%v", err)
87		}
88		if string(got) != string(want) {
89			t.Fatalf("%s不得改写原文件\nwant=%q\n got=%q", label, want, got)
90		}
91	}
92	
93	// assertConflictAccessRejected 用指定命令访问冲突文件：必须退出码 2、
94	// stdout 没有任何业务内容，stderr 点名文件、学生、要求与两个免修编号。
95	func assertConflictAccessRejected(t *testing.T, file string, raw []byte,
96		args []string, student, req, w1, w2 string, label string) {
97		t.Helper()
98		out, errText, code := runCLI(t, file, args...)
99		if code != exitFile {
100			t.Fatalf("%s：访问含两份有效免修的记录应退出码 %d，code=%d out=%q err=%q",
101				label, exitFile, code, out, errText)
102		}
103		if out != "" {
104			t.Fatalf("%s：拒绝整份记录时不应输出任何业务结果，out=%q", label, out)
105		}
106		for _, want := range []string{file, "内容损坏", student, req, w1, w2} {
107			if !strings.Contains(errText, want) {
108				t.Fatalf("%s：错误输出应点名文件/学生 %s/要求 %s/免修 %s、%s（缺 %q），err=%q",
109					label, student, req, w1, w2, want, errText)
110			}
111		}
112		if !strings.Contains(errText, "有效免修 "+w1) ||
113			!strings.Contains(errText, w2) {
114			t.Fatalf("%s：错误应说明同一要求存在两份有效免修 %s 与 %s，err=%q",
115				label, w1, w2, errText)
116		}
117		assertFileByteIdentical(t, file, raw, label+"：")
118	}
119	
120	// conflictRecord 构造结构完整、引用齐全的记录：s1 的 r1 指向 4 学分课程 c1，
121	// 同一要求下有两份编号不同、依据非空的有效免修。withPass 时再附一条已通过
122	// 修读，用于证明通过记录不能掩盖冲突。
123	func conflictRecord(withPass bool) *diskRecord {
124		d := &diskRecord{
125			Version: 1,
126			Courses: []diskCourse{
127				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
128			},
129			Students:     []diskStudent{{ID: "s1"}},
130			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
131			Waivers: []diskWaiver{
132				{ID: "w1", Student: "s1", Req: "r1", Basis: "学科竞赛获奖", Status: "approved"},
133				{ID: "w2", Student: "s1", Req: "r1", Basis: "外校同层次课程", Status: "approved"},
134			},
135		}
136		if withPass {
137			d.Enrollments = []diskEnr{{
138				ID: "e1", Student: "s1", Req: "r1", Term: "2024春",
139				Result: "passed", ResultSeq: 1,
140			}}
141			d.NextResultSeq = 1
142		}
143		return d
144	}
145	
146	// TestCLIDuplicateApprovedWaiversInFileRejectsAllCommands 文件完整可解析，
147	// 但 s1 的 r1 下有两份有效免修 w1、w2：check、show、列出课程乃至写入类命令
148	// 都必须退出码 2，不输出核对结果或登记成功信息，错误点名四要素且文件保留。
149	func TestCLIDuplicateApprovedWaiversInFileRejectsAllCommands(t *testing.T) {
150		file, raw := writeDiskRecord(t, conflictRecord(false))
151	
152		// 只读核对：不能挑其中一份免修继续核对，也不能出现总学分。
153		assertConflictAccessRejected(t, file, raw,
154			[]string{"check", "s1"}, "s1", "r1", "w1", "w2", "check 当事学生")
155	
156		// 历史查看同样拒绝：不能展示任何一份看似正常的免修。
157		assertConflictAccessRejected(t, file, raw,
158			[]string{"show", "s1"}, "s1", "r1", "w1", "w2", "show 当事学生")
159	
160		// 与冲突无关的只读命令也要在加载阶段整份拒绝。
161		assertConflictAccessRejected(t, file, raw,
162			[]string{"list-courses"}, "s1", "r1", "w1", "w2", "list-courses")
163	
164		// 写入类命令：不能报告登记成功，更不能把冲突文件覆盖成“干净”的新记录。
165		assertConflictAccessRejected(t, file, raw,
166			[]string{"student", "s9"}, "s1", "r1", "w1", "w2", "写入类命令 student")
167	
168		// 针对另一名尚未出现在文件里的学生核对：文件整体不可读，仍退出码 2。
169		assertConflictAccessRejected(t, file, raw,
170			[]string{"check", "ghost"}, "s1", "r1", "w1", "w2", "check 其他学生")
171	
172		assertFileByteIdentical(t, file, raw, "全部访问后：")
173	}
174	
175	// TestCLIDuplicateApprovedWaiversNotMaskedByPassedEnrollment 即使目标要求
176	// 另有通过修读（本来足以满足要求），两份有效免修的冲突仍必须以退出码 2
177	// 拒绝整份记录：不能拿着通过结果输出学分核对，文件原样保留。
178	func TestCLIDuplicateApprovedWaiversNotMaskedByPassedEnrollment(t *testing.T) {
179		file, raw := writeDiskRecord(t, conflictRecord(true))
180	
181		out, errText, code := runCLI(t, file, "check", "s1")
182		if code != exitFile {
183			t.Fatalf("通过修读不能掩盖免修冲突，code=%d out=%q err=%q", code, out, errText)
184		}
185		if out != "" || strings.Contains(out, "总学分") || strings.Contains(out, "通过修读") {
186			t.Fatalf("冲突记录不得输出任何学分核对结果，out=%q", out)
187		}
188		if !strings.Contains(errText, "内容损坏") || !strings.Contains(errText, "w1") ||
189			!strings.Contains(errText, "w2") || !strings.Contains(errText, "r1") {
190			t.Fatalf("错误仍应点名 r1 下冲突的 w1/w2，err=%q", errText)
191		}
192		assertFileByteIdentical(t, file, raw, "带通过修读的冲突文件：")
193	}
194	
195	// TestCLIDuplicateApprovedWaiversRejectsEntireFileForOtherStudent 文件里
196	// 另有一名完全合法的学生 s2（自己的课程、自己的要求 r1、自己的一份有效
197	// 免修 w1）：s1 名下的冲突仍然让整份文件不可读，连查询 s2 都退出码 2，
198	// 错误归属 s1 而不是把 s2 的同号记录误报成重复取代。
199	func TestCLIDuplicateApprovedWaiversRejectsEntireFileForOtherStudent(t *testing.T) {
200		d := conflictRecord(false)
201		d.Courses = append(d.Courses, diskCourse{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
202		d.Students = append(d.Students, diskStudent{ID: "s2"})
203		d.Requirements = append(d.Requirements, diskReq{ID: "r1", Student: "s2", Course: "c2"})
204		d.Waivers = append(d.Waivers, diskWaiver{
205			ID: "w1", Student: "s2", Req: "r1", Basis: "s2 本人的依据", Status: "approved",
206		})
207		file, raw := writeDiskRecord(t, d)
208	
209		// 查询完全合法的 s2 也必须整份拒绝：唯一性冲突破坏的是整份文件。
210		out, errText, code := runCLI(t, file, "check", "s2")
211		if code != exitFile || out != "" {
212			t.Fatalf("s1 的冲突应让整份文件不可读，连 s2 都查不了，code=%d out=%q err=%q",
213				code, out, errText)
214		}
215		if !strings.Contains(errText, "s1") || !strings.Contains(errText, "r1") ||
216			!strings.Contains(errText, "w1") || !strings.Contains(errText, "w2") {
217			t.Fatalf("错误应归属 s1 的 r1 与 w1/w2，err=%q", errText)
218		}
219		if strings.Contains(errText, "学生 s2") {
220			t.Fatalf("s2 只有一份有效免修，不应被点名为冲突方，err=%q", errText)
221		}
222		assertFileByteIdentical(t, file, raw, "含无关合法学生的冲突文件：")
223	}
224	
225	// mixedWaiverRecord 构造同一要求 r1 下一份有效免修 wa、一份已拒绝 wr、
226	// 一份已撤销 wv 的合法记录，历史排列由调用方给定。
227	func mixedWaiverRecord(t *testing.T, order []string) (*diskRecord, map[string]diskWaiver) {
228		t.Helper()
229		byID := map[string]diskWaiver{
230			"wa": {ID: "wa", Student: "s1", Req: "r1", Basis: "外校同层次课程", Status: "approved"},
231			"wr": {ID: "wr", Student: "s1", Req: "r1", Basis: "再次申请的新依据",
232				Status: "rejected", Reason: "该要求已有有效免修 wa"},
233			"wv": {ID: "wv", Student: "s1", Req: "r1", Basis: "原竞赛材料",
234				Status: "revoked", Reason: "材料无法核实"},
235		}
236		d := &diskRecord{
237			Version:      1,
238			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
239			Students:     []diskStudent{{ID: "s1"}},
240			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
241		}
242		for _, id := range order {
243			d.Waivers = append(d.Waivers, byID[id])
244		}
245		return d, byID
246	}
247	
248	// TestCLIMixedWaiverHistoryOpensWithSingleValidSource 同一要求下一份有效免修
249	// 与已拒绝、已撤销申请共存的记录必须能正常打开：核对只以有效免修 wa 说明
250	// 来源、4 学分只计一次；check 与 show 都完整保留三份申请的编号、依据、状态
251	// 及原有拒绝/撤销原因，失效申请不重新参与满足；历史排在有效申请前后结论
252	// 相同；只读访问不改文件。
253	func TestCLIMixedWaiverHistoryOpensWithSingleValidSource(t *testing.T) {
254		for name, order := range map[string][]string{
255			"有效申请在最前": {"wa", "wr", "wv"},
256			"有效申请在最后": {"wr", "wv", "wa"},
257		} {
258			t.Run(name, func(t *testing.T) {
259				d, _ := mixedWaiverRecord(t, order)
260				file, raw := writeDiskRecord(t, d)
261	
262				out, _, code := runCLI(t, file, "check", "s1")
263				if code != 0 {
264					t.Fatalf("合法混合历史应正常核对，code=%d out=%q", code, out)
265				}
266				for _, want := range []string{
267					"总学分：4",
268					"要求 r1（课程 c1《高等数学》，4 学分）：已满足",
269					"来源为有效免修 wa",
270					"被拒绝的免修：",
271					`免修 wr（要求 r1，依据 "再次申请的新依据"）：该要求已有有效免修 wa`,
272					"已撤销免修：[wv]",
273				} {
274					if !strings.Contains(out, want) {
275						t.Fatalf("核对结果应包含 %q，out=%q", want, out)
276					}
277				}
278				if strings.Contains(out, "未满足要求：[") {
279					t.Fatalf("r1 应由有效免修满足，不应列为未满足，out=%q", out)
280				}
281				// 只能有一份有效来源：wa 只出现一次，失效申请不能被描述成来源。
282				if strings.Count(out, "来源为有效免修 wa") != 1 {
283					t.Fatalf("有效免修来源应只计一次，out=%q", out)
284				}
285	
286				// show 保留三份申请各自的编号、依据、状态与括号中的原有原因。
287				show, _, code := runCLI(t, file, "show", "s1")
288				if code != 0 {
289					t.Fatalf("show 合法混合历史应成功，code=%d out=%q", code, show)
290				}
291				for _, want := range []string{
292					`免修 wa：要求 r1，依据 "外校同层次课程"，状态：有效`,
293					`免修 wr：要求 r1，依据 "再次申请的新依据"，状态：已拒绝（该要求已有有效免修 wa）`,
294					`免修 wv：要求 r1，依据 "原竞赛材料"，状态：已撤销（材料无法核实）`,
295				} {
296					if !strings.Contains(show, want) {
297						t.Fatalf("历史查看应完整保留 %q，out=%q", want, show)
298					}
299				}
300				// 三份申请所在行各只出现一次，不能为去重丢掉历史或重复列出。
301				for _, line := range []string{
302					"免修 wa：要求 r1",
303					"免修 wr：要求 r1",
304					"免修 wv：要求 r1",
305				} {
306					if strings.Count(show, line) != 1 {
307						t.Fatalf("show 中 %q 应恰好出现一次，out=%q", line, show)
308					}
309				}
310	
311				// 只读访问不得改动合法记录。
312				assertFileByteIdentical(t, file, raw, "check/show 之后：")
313			})
314		}
315	}
316	
317	// TestCLIInvalidOnlyWaiverHistoryLeavesRequirementUnmet 文件里只有已拒绝与
318	// 已撤销申请（没有有效免修）时记录合法、可正常打开，但要求必须未满足、
319	// 学分为零，两份历史及原因仍可在 check/show 中查到。
320	func TestCLIInvalidOnlyWaiverHistoryLeavesRequirementUnmet(t *testing.T) {
321		d := &diskRecord{
322			Version:      1,
323			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
324			Students:     []diskStudent{{ID: "s1"}},
325			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
326			Waivers: []diskWaiver{
327				{ID: "wr", Student: "s1", Req: "r1", Basis: "材料不全",
328					Status: "rejected", Reason: "免修依据为空"},
329				{ID: "wv", Student: "s1", Req: "r1", Basis: "旧竞赛获奖",
330					Status: "revoked", Reason: "材料无法核实"},
331			},
332		}
333		file, raw := writeDiskRecord(t, d)
334	
335		out, _, code := runCLI(t, file, "check", "s1")
336		if code != 0 {
337			t.Fatalf("仅失效申请的记录应正常核对，code=%d out=%q", code, out)
338		}
339		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") ||
340			strings.Contains(out, "来源为有效免修") {
341			t.Fatalf("失效申请不能满足要求或成为来源，out=%q", out)
342		}
343		if !strings.Contains(out, "免修 wr") || !strings.Contains(out, "免修依据为空") ||
344			!strings.Contains(out, "已撤销免修：[wv]") {
345			t.Fatalf("被拒绝与已撤销历史及原因仍应列出，out=%q", out)
346		}
347		show, _, _ := runCLI(t, file, "show", "s1")
348		if !strings.Contains(show, "状态：已拒绝（免修依据为空）") ||
349			!strings.Contains(show, "状态：已撤销（材料无法核实）") {
350			t.Fatalf("show 应保留两份失效申请的状态与原因，out=%q", show)
351		}
352		assertFileByteIdentical(t, file, raw, "只读查询之后：")
353	}
354	
355	// TestCLISameReqAndWaiverIDAcrossStudentsFromFile 唯一性只作用于同一学生
356	// 名下的同一要求：两名学生各自使用相同的要求编号 r1、相同的免修编号 w1，
357	// 只要各自只有一份有效申请就正常读取；两人的要求指向不同学分课程时，
358	// 核对分别得到本人的课程学分与免修来源，不能误报重复取代。
359	func TestCLISameReqAndWaiverIDAcrossStudentsFromFile(t *testing.T) {
360		d := &diskRecord{
361			Version: 1,
362			Courses: []diskCourse{
363				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
364				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
365			},
366			Students: []diskStudent{{ID: "s1"}, {ID: "s2"}},
367			Requirements: []diskReq{
368				{ID: "r1", Student: "s1", Course: "c1"},
369				{ID: "r1", Student: "s2", Course: "c2"},
370			},
371			Waivers: []diskWaiver{
372				{ID: "w1", Student: "s1", Req: "r1", Basis: "s1 的竞赛获奖", Status: "approved"},
373				{ID: "w1", Student: "s2", Req: "r1", Basis: "s2 的外校修读", Status: "approved"},
374			},
375		}
376		file, raw := writeDiskRecord(t, d)
377	
378		out, _, code := runCLI(t, file, "check", "s1")
379		if code != 0 {
380			t.Fatalf("s1 的合法记录应正常核对，code=%d out=%q", code, out)
381		}
382		if !strings.Contains(out, "总学分：4") ||
383			!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：已满足") ||
384			!strings.Contains(out, "来源为有效免修 w1") ||
385			strings.Contains(out, "未满足要求：[") {
386			t.Fatalf("s1 应凭本人 w1 获得本人课程的 4 学分，out=%q", out)
387		}
388	
389		out, _, code = runCLI(t, file, "check", "s2")
390		if code != 0 {
391			t.Fatalf("s2 的合法记录应正常核对，code=%d out=%q", code, out)
392		}
393		if !strings.Contains(out, "总学分：3") ||
394			!strings.Contains(out, "要求 r1（课程 c2《线性代数》，3 学分）：已满足") ||
395			!strings.Contains(out, "来源为有效免修 w1") {
396			t.Fatalf("s2 应凭本人 w1 获得本人课程的 3 学分，不能误报重复取代，out=%q", out)
397		}
398	
399		// 历史各归各：show 中只能看到本人依据，不能串到另一人。
400		show1, _, _ := runCLI(t, file, "show", "s1")
401		if !strings.Contains(show1, `免修 w1：要求 r1，依据 "s1 的竞赛获奖"，状态：有效`) ||
402			strings.Contains(show1, "s2 的外校修读") {
403			t.Fatalf("s1 的历史应只含本人 w1 与依据，out=%q", show1)
404		}
405		show2, _, _ := runCLI(t, file, "show", "s2")
406		if !strings.Contains(show2, `免修 w1：要求 r1，依据 "s2 的外校修读"，状态：有效`) ||
407			strings.Contains(show2, "s1 的竞赛获奖") {
408			t.Fatalf("s2 的历史应只含本人 w1 与依据，out=%q", show2)
409		}
410	
411		assertFileByteIdentical(t, file, raw, "跨学生同号合法记录只读之后：")
412	}
413

